<section class="page-intro shell"><span class="eyebrow">ORDER HISTORY</span><h1>আপনার কেনাকাটা।</h1><p>অর্ডারের সর্বশেষ অবস্থা এবং বিস্তারিত দেখুন।</p></section><section class="section shell"><?php if(empty($data['orders'])): ?><div class="empty-state"><h2>এখনো কোনো অর্ডার নেই।</h2><a class="button button-green" href="/shop">পণ্য দেখুন</a></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>অর্ডার</th><th>তারিখ</th><th>অবস্থা</th><th>পেমেন্ট</th><th>মোট</th><th></th></tr></thead><tbody><?php foreach($data['orders'] as $order): ?><tr><td><?= e($order['order_number']) ?></td><td><?= e(date('d M Y',strtotime($order['placed_at']))) ?></td><td><span class="status-pill"><?= e($order['status']) ?></span></td><td><?= e($order['payment_status']) ?></td><td><?= e(format_price((float)$order['grand_total'],$order['currency'])) ?></td><td><a href="/account/orders/<?= e($order['id']) ?>">বিস্তারিত</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
